$insertados = []; $saltados = [];
$chk = $pdo->prepare("SELECT id FROM listas_excel WHERE nombre=?");
$ins = $pdo->prepare("INSERT INTO listas_excel (nombre,descripcion,columnas,creado_por) VALUES (?,?,?,?)");

foreach ($rows as $r) {
    [$nombre,$desc,$cols] = $r;
    $chk->execute([$nombre]);
    if ($chk->fetch()) { $saltados[] = $nombre; continue; }
    $ins->execute([$nombre, $desc, $cols, $uid]);
    $insertados[] = $nombre;
}
?>
