</style></head><body>
<div class="box">
<h1>📊 Importación del catálogo de LISTAS</h1>
<p>
  <span class="tag"><?= count($insertados) ?> insertadas</span>
  &nbsp;<span class="tag tag2"><?= count($saltados) ?> ya existían (saltadas)</span>
</p>

<?php if ($insertados): ?>
<h3 class="ok">✓ Insertadas</h3>
<ul><?php foreach ($insertados as $i): ?><li><?= htmlspecialchars($i) ?></li><?php endforeach; ?></ul>
<?php endif; ?>

<?php if ($saltados): ?>
<h3 class="skip">↺ Ya existían (no se duplicaron)</h3>
<ul><?php foreach ($saltados as $i): ?><li><?= htmlspecialchars($i) ?></li><?php endforeach; ?></ul>
<?php endif; ?>

